-- Exercise muscle tags, where each came from, and "Wrong muscle?" reports.
--
-- What it adds (all new; no existing table, policy or function changes):
--   exercise_muscle_tags     one row per muscle tag per source (free-exercise-db, wger, Theryn library, review)
--   exercise_muscle_status   the current main muscle per exercise and how it was checked
--   exercise_muscle_reports  reports from the app's exercise info sheet
--   report_exercise_muscle() called by the app; signed-in users only
--   review_exercise_muscle() for reviewers; calls assert_admin() from 20260920173034_admin_health_and_stats.sql
--                            (if that function is missing, review fails closed with "function does not exist")
-- exercise_ref is the free-exercise-db id the app's picker uses (public/exercises.json "id").
-- Seeds 872 exercises and 2714 tags from the 2026-09-26 agreement check
-- (see ~/Downloads/GYM App/Theryn-exercise-matcher-2026-09-26/consensus.js). Safe to run more than once.
-- Proven in PGlite with Supabase-like roles and RLS: test-migration.js in that folder.


-- Step 3: one row per tag per source, so any tag can be traced.
CREATE TABLE IF NOT EXISTS public.exercise_muscle_tags (
  exercise_ref text NOT NULL,
  muscle       text NOT NULL,
  role         text NOT NULL CHECK (role IN ('main','helper')),
  source       text NOT NULL CHECK (source IN ('free_exercise_db','wger','theryn_library','theryn_review','reviewer')),
  source_ref   text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (exercise_ref, muscle, role, source)
);

-- The current answer for each exercise, and how sure we are.
CREATE TABLE IF NOT EXISTS public.exercise_muscle_status (
  exercise_ref text PRIMARY KEY,
  main_muscle  text NOT NULL,
  status       text NOT NULL CHECK (status IN ('confirmed','needs_review','unchecked','reviewer_checked')),
  reason       text,
  checked_by   uuid,
  checked_at   timestamptz,
  reference    text,
  open_reports int NOT NULL DEFAULT 0,
  updated_at   timestamptz NOT NULL DEFAULT now()
);

-- Step 4: "wrong muscle?" reports from coaches and athletes.
CREATE TABLE IF NOT EXISTS public.exercise_muscle_reports (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exercise_ref     text NOT NULL REFERENCES public.exercise_muscle_status(exercise_ref),
  reporter         uuid NOT NULL,
  suggested_muscle text NOT NULL,
  note             text CHECK (note IS NULL OR char_length(note) <= 300),
  status           text NOT NULL DEFAULT 'open' CHECK (status IN ('open','accepted','rejected')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  resolved_by      uuid,
  resolved_at      timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS exercise_muscle_reports_one_open ON public.exercise_muscle_reports (exercise_ref, reporter) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS exercise_muscle_reports_queue ON public.exercise_muscle_reports (status, exercise_ref);

CREATE OR REPLACE FUNCTION public.exercise_muscle_ok(m text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = pg_catalog AS $$
  SELECT m IN ('chest','shoulders','biceps','triceps','forearms','abs','traps','upperback','lowerback','glutes','quads','hamstrings','adductors','calves','neck')
$$;

-- Everyone signed in can read tags and status. Nobody writes them directly.
ALTER TABLE public.exercise_muscle_tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exercise_muscle_status ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exercise_muscle_reports ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Signed-in users read muscle tags" ON public.exercise_muscle_tags;
CREATE POLICY "Signed-in users read muscle tags" ON public.exercise_muscle_tags FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Signed-in users read muscle status" ON public.exercise_muscle_status;
CREATE POLICY "Signed-in users read muscle status" ON public.exercise_muscle_status FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Reporters read own reports, admins read all" ON public.exercise_muscle_reports;
CREATE POLICY "Reporters read own reports, admins read all" ON public.exercise_muscle_reports FOR SELECT TO authenticated
  USING (reporter = (SELECT auth.uid()) OR public.is_admin());
REVOKE ALL ON public.exercise_muscle_tags, public.exercise_muscle_status, public.exercise_muscle_reports FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.exercise_muscle_tags, public.exercise_muscle_status, public.exercise_muscle_reports FROM authenticated;

-- A coach or athlete says the main muscle is wrong.
-- Unchecked or already-disputed exercises go straight to review.
-- A confirmed or reviewer-checked exercise needs 3 different people, so one mistaken report can't undo it.
CREATE OR REPLACE FUNCTION public.report_exercise_muscle(p_exercise text, p_suggested text, p_note text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE me uuid := auth.uid(); s public.exercise_muscle_status; people int; mine int;
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION 'sign in to report' USING ERRCODE = '42501'; END IF;
  IF NOT public.exercise_muscle_ok(p_suggested) THEN RAISE EXCEPTION 'unknown muscle: %', p_suggested USING ERRCODE = '22023'; END IF;
  SELECT * INTO s FROM public.exercise_muscle_status WHERE exercise_ref = p_exercise FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown exercise' USING ERRCODE = '22023'; END IF;
  IF s.main_muscle = p_suggested THEN RAISE EXCEPTION 'that is already the main muscle' USING ERRCODE = '22023'; END IF;
  SELECT count(*) INTO mine FROM public.exercise_muscle_reports WHERE reporter = me AND status = 'open';
  IF mine >= 20 THEN RAISE EXCEPTION 'too many open reports' USING ERRCODE = '54000'; END IF;
  INSERT INTO public.exercise_muscle_reports (exercise_ref, reporter, suggested_muscle, note)
  VALUES (p_exercise, me, p_suggested, nullif(btrim(p_note), ''));
  SELECT count(DISTINCT reporter) INTO people FROM public.exercise_muscle_reports WHERE exercise_ref = p_exercise AND status = 'open';
  UPDATE public.exercise_muscle_status SET open_reports = people, updated_at = now(),
    status = CASE WHEN s.status IN ('unchecked','needs_review') OR people >= 3 THEN 'needs_review' ELSE s.status END,
    reason = CASE WHEN s.status IN ('unchecked','needs_review') OR people >= 3
                  THEN concat_ws('; ', nullif(s.reason, ''), people || ' report(s): wrong main muscle') ELSE s.reason END
  WHERE exercise_ref = p_exercise
  RETURNING status INTO s.status;
  RETURN s.status;
END $$;

-- A reviewer (admin) settles it, citing the reference they used. Open reports are closed as accepted or rejected.
CREATE OR REPLACE FUNCTION public.review_exercise_muscle(p_exercise text, p_main text, p_helpers text[], p_reference text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE me uuid := auth.uid(); h text;
BEGIN
  PERFORM public.assert_admin();
  IF NOT public.exercise_muscle_ok(p_main) THEN RAISE EXCEPTION 'unknown muscle: %', p_main USING ERRCODE = '22023'; END IF;
  IF p_reference IS NULL OR char_length(btrim(p_reference)) < 3 THEN RAISE EXCEPTION 'say which reference you checked' USING ERRCODE = '22023'; END IF;
  UPDATE public.exercise_muscle_status SET main_muscle = p_main, status = 'reviewer_checked', reason = 'checked by a reviewer',
    checked_by = me, checked_at = now(), reference = btrim(p_reference), open_reports = 0, updated_at = now()
  WHERE exercise_ref = p_exercise;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown exercise' USING ERRCODE = '22023'; END IF;
  DELETE FROM public.exercise_muscle_tags WHERE exercise_ref = p_exercise AND source = 'reviewer';
  INSERT INTO public.exercise_muscle_tags (exercise_ref, muscle, role, source, source_ref) VALUES (p_exercise, p_main, 'main', 'reviewer', btrim(p_reference));
  FOREACH h IN ARRAY coalesce(p_helpers, '{}') LOOP
    IF public.exercise_muscle_ok(h) AND h <> p_main THEN
      INSERT INTO public.exercise_muscle_tags (exercise_ref, muscle, role, source, source_ref) VALUES (p_exercise, h, 'helper', 'reviewer', btrim(p_reference)) ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
  UPDATE public.exercise_muscle_reports SET status = CASE WHEN suggested_muscle = p_main THEN 'accepted' ELSE 'rejected' END,
    resolved_by = me, resolved_at = now()
  WHERE exercise_ref = p_exercise AND status = 'open';
END $$;

REVOKE ALL ON FUNCTION public.exercise_muscle_ok(text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.exercise_muscle_ok(text) FROM anon;
GRANT EXECUTE ON FUNCTION public.exercise_muscle_ok(text) TO authenticated;
REVOKE ALL ON FUNCTION public.report_exercise_muscle(text, text, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.report_exercise_muscle(text, text, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.report_exercise_muscle(text, text, text) TO authenticated;
REVOKE ALL ON FUNCTION public.review_exercise_muscle(text, text, text[], text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.review_exercise_muscle(text, text, text[], text) FROM anon;
GRANT EXECUTE ON FUNCTION public.review_exercise_muscle(text, text, text[], text) TO authenticated;

